"""Durations written like 1d1h30m or 1 hour 30 minutes."""
import re


_SECONDS = {
    "d": 86400, "day": 86400, "days": 86400,
    "h": 3600, "hour": 3600, "hours": 3600,
    "m": 60, "minute": 60, "minutes": 60,
    "s": 1, "second": 1, "seconds": 1,
}

_PAIR = re.compile(r"(\d+(?:\.\d+)?)\s*([a-z]+)")


def parse_duration(text):
    """Parse durations like '1d1h30m', '1 hour 30 minutes', '45s', or '1.5h' into whole seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    stripped = text.replace(" ", "").replace("\t", "")
    if not stripped or _PAIR.sub("", stripped):
        # Empty, or anything left over after removing number+unit pairs.
        raise ValueError(f"invalid duration: {text!r}")
    total = 0.0
    for value, unit in _PAIR.findall(stripped):
        if unit not in _SECONDS:
            raise ValueError(f"invalid duration: {text!r}")
        total += float(value) * _SECONDS[unit]
    if total != int(total):
        raise ValueError(f"invalid duration: {text!r}")
    return int(total)


def format_duration(seconds):
    """Format whole seconds as the shortest string parse_duration accepts."""
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("seconds must be an int")
    parts = []
    for divisor, suffix in ((86400, "d"), (3600, "h"), (60, "m"), (1, "s")):
        value, seconds = divmod(seconds, divisor)
        if value:
            parts.append(f"{value}{suffix}")
    return "".join(parts) or "0s"

