#!/usr/bin/env python3
"""Read one duration per line from stdin and print the total."""

import sys

from durations import parse_duration, format_duration


def main() -> int:
    total = 0
    for lineno, line in enumerate(sys.stdin, start=1):
        text = line.strip()
        if not text:
            continue
        try:
            total += parse_duration(text)
        except ValueError:
            print(f"invalid duration on line {lineno}: {text!r}", file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())
